import type { PluginManifest } from './types.js';

export const HOST_API_VERSION = 1;

export function validateManifest(m: PluginManifest): string[] {
  const errors: string[] = [];
  if (!m.name) errors.push('manifest.name is required');
  if (m.apiVersion !== HOST_API_VERSION) errors.push(`apiVersion ${m.apiVersion} is not supported`);
  return errors;
}

