files.src/sandbox/pool.ts:
import { runRuleInWorker } from './worker.js';

export const RULE_TIMEOUT_MS = 2000;

export function runWithTimeout(pluginPath: string, rule: string, ast: unknown) {
  const w = runRuleInWorker(pluginPath, rule, ast);
  const timer = setTimeout(() => w.terminate(), RULE_TIMEOUT_MS);
  return new Promise((resolve, reject) => {
    w.once('message', (m) => { clearTimeout(timer); resolve(m); });
    w.once('error', reject);
  });
}

