import { createHash } from 'node:crypto';

const asts = new Map<string, unknown>();

export function cachedParse(sql: string, parse: (s: string) => unknown) {
  const key = createHash('sha256').update(sql).digest('hex');
  if (!asts.has(key)) asts.set(key, parse(sql));
  return asts.get(key);
}

