import { rm, stat } from 'node:fs/promises';

export async function invalidateOnConfigChange(configPath: string, lastMtime: number) {
  const { mtimeMs } = await stat(configPath);
  if (mtimeMs > lastMtime) await rm('.migralint/cache', { recursive: true, force: true });
  return mtimeMs;
}

