import { writeFile } from 'node:fs/promises';
import type { LockEntry } from '../pluginlock/format.js';
import { LOCKFILE } from '../pluginlock/format.js';

export async function writeLock(entries: LockEntry[]) {
  const lines = entries.map((e) => `${e.name} ${e.version} ${e.integrity}`);
  await writeFile(LOCKFILE, lines.join('\n') + '\n');
}

files.src/lockwriter/sort.ts:
import type { LockEntry } from '../pluginlock/format.js';

export function sortEntries(entries: LockEntry[]): LockEntry[] {
  return [...entries].sort((a, b) => a.name.localeCompare(b.name));
}

